use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let n = input.as_i64().unwrap();
    let edges = input.as_array().unwrap();
    let mut graph = vec![vec![]; n as usize];
    for edge in edges {
        let u = edge[0].as_i64().unwrap();
        let v = edge[1].as_i64().unwrap();
        graph[u as usize].push(v as usize);
        graph[v as usize].push(u as usize);
    }
    let mut stack = vec![];
    let mut result = Vec::new();
    for i in 0..n {
        if graph[i].is_empty() {
            stack.push(i);
        }
    }
    while let Some(u) = stack.pop() {
        result.push(u);
        for v in graph[u] {
            graph[v].remove(&u);
            if graph[v].is_empty() {
                stack.push(v);
            }
        }
    }
    if result.is_empty() {
        Value::Null
    } else {
        Value::Array(result.into_iter().map(|v| Value::Number(v as f64)).collect())
    }
}
